#!/usr/bin/env python3
import base64
import gzip
import subprocess
from pathlib import Path

PATCH_B64 = ""

patch = gzip.decompress(base64.b64decode(PATCH_B64))
patch_path = Path("/tmp/global-hardening-final.patch")
patch_path.write_bytes(patch)
subprocess.run(["git", "apply", "--check", str(patch_path)], check=True)
subprocess.run(["git", "apply", str(patch_path)], check=True)
print(f"Applied final global hardening patch ({len(patch)} bytes)")
